if(localStorage.getItem('hk-storage-version')!==STORAGE_VERSION){
 Object.keys(localStorage).filter(k=>k.startsWith('hk-')).forEach(k=>localStorage.removeItem(k));
 localStorage.setItem('hk-storage-version',STORAGE_VERSION);
}
const savedToken=localStorage.getItem('hk-token')||'';
const userIdFromToken=token=>{try{return JSON.parse(atob(String(token||'').split('.')[0].replace(/-/g,'+').replace(/_/g,'/'))).userId||''}catch{return ''}};
const userKey=(name,token=savedToken)=>`hk-${name}:${userIdFromToken(token)||'anonymous'}`;
const chatKey=token=>`hk-chat:${userIdFromToken(token)||'anonymous'}`;
const CHAT_ACTION_MARKER=/\[\[\s*HKP_ACTION(?:_V1)?\s*:\s*(ASSESS_PRE_HK|ASSESS_IN_HK|ASSESS_CROSS_BORDER|ACCOUNT_SYNC_REQUIRED)\s*\]\]/gi;
function normalizeChatMessage(message){
 if(!message||message.role!=='assistant')return message;
 const found=[];
 const content=String(message.content||'').replace(CHAT_ACTION_MARKER,(_marker,code)=>{found.push(String(code).toUpperCase());return ''}).replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();
 let type=message.action?.type||'';
 if(found.includes('ACCOUNT_SYNC_REQUIRED'))type='account_sync_required';
 else if(found.includes('ASSESS_CROSS_BORDER'))type='assess_cross_border';
 else if(found.includes('ASSESS_PRE_HK'))type='assess_pre_hk';
 else if(found.includes('ASSESS_PRE_HK'))type='assess_pre_hk';
 else if(found.includes('ASSESS_IN_HK'))type='';
 return {...message,content,action:type?{type}:null};
}
const clearTransientChatActions=messages=>(Array.isArray(messages)?messages:[]).map(normalizeChatMessage).map(message=>message?.action?.type==='account_sync_required'?{...message,action:null}:message);
const readCachedChat=token=>{try{return clearTransientChatActions(JSON.parse(localStorage.getItem(chatKey(token))||'[]'))}catch{return []}};
