const providerCacheKey=id=>`${providerPlanVersion()}:${id}`;
const providerIds=home=>[...(home?.recommendations||[]).map(x=>x.providerRecordId||x.provider?.recordId),...(home?.actions||[]).flatMap(x=>(x.providers||[]).map(p=>p.providerRecordId||p.provider?.recordId))].filter(Boolean);
async function fetchProviderDetail(id){const key=providerCacheKey(id),cached=providerCache.get(key);if(cached?.provider)return cached.provider;if(cached?.pending)return cached.pending;const pending=api('/api/providers/'+encodeURIComponent(id)).then(d=>{providerCache.set(key,{provider:d.provider});return d.provider;}).catch(error=>{providerCache.delete(key);throw error;});providerCache.set(key,{pending});return pending;}
