function api(path,opts={}){return fetch(path,{...opts,headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`}:{})}}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'请求失败');return d;});}
async function syncAccountAfterLogin(loginToken){
 for(let attempt=0;attempt<2;attempt++)try{
  const response=await fetch('/api/account/sync',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${loginToken}`}});
  const data=await response.json();
  if(!response.ok||!data.synced||!data.token||state.token!==loginToken)throw new Error('账号同步未完成');
  const previousToken=state.token,previousChat=clearTransientChatActions(readCachedChat(previousToken));
  state.token=data.token;
  state.phone=data.user?.phone||state.phone;
  localStorage.setItem('hk-token',data.token);
  localStorage.setItem('hk-phone',state.phone);
  if(previousChat.length&&!readCachedChat(data.token).length)localStorage.setItem(chatKey(data.token),JSON.stringify(previousChat));
  if(userIdFromToken(previousToken)!==userIdFromToken(data.token)){
   state.chat=clearTransientChatActions(readCachedChat(data.token));
   state.chatLoaded=false;
  }
  return true;
 }catch(error){console.warn('account-sync-attempt-failed',attempt+1,error.message);if(attempt===0)await new Promise(resolve=>setTimeout(resolve,500))}
 return false;
}
