function providerPreview(action){
 const match=action.providers?.[0];
 if(!match)return `<div class="provider-empty"><b>${T('provider.empty.title')}</b><p>${T('provider.empty.body')}</p></div>`;
const p=match.provider,name=p['服务商简称']||p['服务商名称']||'服务商',type=p['服务商类型']||p['机构类型']||'专业服务机构',intro=p['服务商简介']||p['机构简介']||p['简介']||'点击查看服务商的完整资料。',unique=v=>[...new Set(Array.isArray(v)?v:v?[v]:[])],services=unique(p['可提供服务']).slice(0,4),languages=unique(p['服务语言']).slice(0,3),methods=unique(p['办理方式']||p['服务方式']||p['是否支持远程办理']).slice(0,2);
 const displayName=providerRecordText(p,['服务商简称','服务商名称'],state.locale,{identity:true,fallback:localizedBusiness(name,'provider.type')||T('provider.type')}),displayType=providerRecordText(p,['服务商类型','机构类型'],state.locale,{controlled:true,fallback:T('provider.type')}),displayIntro=providerRecordText(p,['服务商简介','机构简介','简介'],state.locale,{fallback:T('provider.intro')}),displayServices=localizedProviderField(services,'provider.services'),displayLanguages=localizedProviderField(languages,'provider.languages'),displayMethods=localizedProviderField(methods,'provider.method');
 return `<div class="provider-recommendation"><button class="figma-provider" data-provider-id="${escape(p.recordId)}"><span class="provider-banner">${escape(displayName)}</span><span class="provider-body"><b>${escape(displayType)}</b><span class="provider-intro">${escape(displayIntro)}</span>${displayServices.length?`<span class="provider-meta"><strong>${T('provider.services')}</strong><i>${displayServices.map(x=>`<em>${escape(x)}</em>`).join('')}</i></span>`:''}${displayLanguages.length?`<span class="provider-meta"><strong>${T('provider.languages')}</strong><i>${displayLanguages.map(x=>`<em>${escape(x)}</em>`).join('')}</i></span>`:''}${displayMethods.length?`<span class="provider-meta"><strong>${T('provider.method')}</strong><i>${displayMethods.map(x=>`<em>${escape(x)}</em>`).join('')}</i></span>`:''}<span class="provider-open" aria-hidden="true">→</span></span></button></div>`
}
