function officialInformation(type='pre-hk'){const items=officialLinks.pre,copy=officialCopy[state.locale];return `<section class="quick-services official-information"><header><div><h2>${escape(copy?.title||translate('官方信息查询',state.locale))}</h2><p>${escape(copy?.subtitle||translate('为你整理香港政府网站的常用查询及资质核验入口。',state.locale))}</p></div></header><div>${items.map((x,i)=>{const labels=copy?.items[i]||x;return `<a href="${x[3]}" target="_blank" rel="noopener noreferrer"><img src="${x[4]}" alt=""><span><b>${escape(labels[0])}</b><small>${escape(labels[1])}</small><i>${escape(labels[2])}　↗</i></span></a>`}).join('')}</div></section>`}
function assessmentEntries(){return `<section class="assessment-entries"><h2>${T('assessment.entry.title')}</h2><p>${T('assessment.entry.subtitle')}</p><article><span>${T('assessment.entry.label')}</span><h3>${T('assessment.entry.name')}</h3><p>${T('assessment.entry.body')}</p><button data-start="pre-hk">${T('assessment.entry.button')}</button></article></section>`}
function supportCopy(action){const raw=action.providerType||action.providers?.[0]?.provider?.['服务商类型']||action.providers?.[0]?.provider?.['机构类型']||'',type=Array.isArray(raw)?raw.join('、'):raw;if(type.includes('律师'))return '这项工作建议由熟悉相关业务的香港律师协助确认。';if(type.includes('会计'))return '这项工作通常需要会计师事务所提供专业支持。';if(type.includes('TCSP'))return '这项工作通常由TCSP持牌公司协助完成。';return '这项工作建议由相应的香港专业服务机构协助确认。'}
function homeResultTitle(type,conclusion,fallback=''){const pre={'适合启动':'你的香港业务可以开始进入落地准备','具备基础':'你的企业已经具备赴港发展的基础','值得探索':'香港可能为你的业务带来新的发展空间','早期准备':'建议先完善业务基础，再确定赴港时间'},inHK={'注册审批中':'可以开始准备公司成立后的第一步','成立待运营':'香港公司已经成立，接下来要把基础安排接上','当前运行基本正常':'目前没有发现明显需要优先处理的事项','有事项待完善':'公司已经具备基本运作条件，但仍有事项需要补齐','需要优先核验':'先确认这些关键事项，再继续推进经营','退出安排待梳理':'先核清公司现状，再决定暂停还是撤销'};return (type==='in-hk'?inHK:pre)[conclusion]||fallback;}
function assessedHome(){const h=state.homeData,r=h.result||{},tags=[...(r.features||[]),...(r.attention||[])].filter(Boolean).slice(0,4),displayTags=tags.map(x=>localizedBusiness(x,'home.result.fallback')).filter(Boolean),title=localizedBusiness(h.title,'home.result.title')||T('home.result.title');return `<section class="assessment-summary"><p>${T('home.result.label')}</p><h2>${escape(title)}</h2><div class="summary-tags">${escape(displayTags.join(' | ')||localizedBusiness(h.conclusion,'home.result.fallback')||T('home.result.fallback'))}</div><div><button class="primary" data-route="result">${T('home.result.view')}</button><button class="secondary" data-start="pre-hk">${T('common.retake')}</button></div></section><section class="priority-section"><header><h2>${T('home.actions.title')}</h2><p>${T('home.actions.summary')}</p></header><div class="personal-actions">${(h.actions||[]).map((a,i)=>{const copy=localizedAction(a),support=localizedBusiness(supportCopy(a),'home.support.title');return `<article class="home-action"><div class="action-heading"><b>${String(i+1).padStart(2,'0')}</b><div><h3>${escape(copy.title)}</h3><p>${escape(copy.reason)}</p><aside><strong>${escape(support)}</strong><span>${T('home.support.providers')}</span></aside></div></div>${providerPreview(a)}</article>`}).join('')}</div></section>${officialInformation(h.type)}`}
function aiLoader(title,detail){return `<div class="ai-loader" role="status" aria-live="polite"><div class="ai-loader-mark" aria-hidden="true"><span class="ai-loader-face"><i></i><i></i></span><b></b><b></b><b></b></div><strong>${escape(title)}</strong><p>${escape(detail)}</p><div class="ai-loader-progress" aria-hidden="true"><i></i></div></div>`}
function homeLoading(){return `<section class="home-loading" aria-busy="true">${aiLoader(T('loading.home.title'),T('loading.home.detail'))}</section>`}
function profilePanel(){return `<div class="profile-curtain" data-action="close-profile"></div><aside class="profile-drawer" aria-label="我的" aria-modal="true" role="dialog"><header><button data-action="close-profile" aria-label="关闭我的">←</button><h2>我的</h2></header>${state.phone?`<div class="profile-head"><span class="avatar">${escape(state.phone.slice(-1))}</span><div><b>${escape(state.phone.slice(0,3)+' **** '+state.phone.slice(-4))}</b></div></div><div class="profile-list"><button data-route="account"><b>账号资料</b><span>手机、称呼与语言偏好　→</span></button><button data-route="company"><b>企业信息表</b><span>查看和编辑已确认的信息　→</span></button><button data-route="assessments"><b>我的评估与计划</b><span>${state.result?'已有 1 份评估结果':'暂无评估'}　→</span></button><button data-route="favorites"><b>收藏的服务商</b><span>查看收藏与比较列表　→</span></button><button data-route="about"><b>关于公司</b><span>${T('profile.aboutLine')}　→</span></button><button data-route="cooperation"><b>商务合作</b><span>服务商与机构合作　→</span></button><button data-route="contact"><b>联系我们</b><span>服务时间与问题反馈　→</span></button></div><div class="drawer-logout"><button class="secondary" data-action="logout">退出登录</button></div>`:`<div class="empty"><p>登录后查看企业信息、评估记录和收藏内容。</p><button class="primary" data-route="login">去登录</button></div>`}</aside>`}
