const guideDescriptions={
  '在香港开设业务':'了解在香港设立企业、开展业务及落地经营前需要准备的事项。','如何办理新公司的注册':'了解香港公司的注册流程、所需文件和基本要求。','本地私人公司周年申报表':'了解私人公司周年申报的时限、费用和提交要求。','注册成立本地有限公司常见问题':'集中了解本地有限公司注册时常见的问题与处理方式。','公司注册处主要收费':'查看公司注册、文件提交及相关服务的官方收费。','创业：牌照、注册及法例':'了解创业可能涉及的牌照、登记和法规要求。','香港的开放营商环境':'了解香港的营商制度、市场环境和企业支持。','借助香港走向全球':'了解企业如何利用香港连接国际市场和商业网络。','香港的连接优势':'了解香港在市场、资金、专业服务和国际网络方面的连接能力。','在香港设立企业及投资':'了解在香港设立企业和开展投资的基础信息。','在香港营商':'了解企业在香港经营涉及的主要政府服务和要求。','商业登记及公司注册':'了解商业登记与公司注册的区别、流程和官方入口。',
  '香港公司成立前后，需要准备哪些事项':'了解公司注册、商业登记、公司架构及开户前准备。','公司成立后，为什么要备存重要控制人登记册':'了解重要控制人的识别、登记册及指定代表要求。','开始经营后，需要保留哪些业务资料':'了解收入、付款、发票、银行结单及业务纪录要求。','香港公司成立后，如何开始实际经营':'了解商业登记、公司架构、银行账户及营商准备。','私人公司什么时候需要提交周年申报表':'了解NAR1、申报时限、费用及提交方法。','还没有收入，也要准备会计记录吗':'了解公司开展业务后需要持续保存的基本纪录。','香港公司的年度维护事项有哪些':'了解周年申报、公司资料和提交时限。','业务单据和会计记录需要保存多久':'了解业务纪录类型及保存要求。','香港公司如何通过商业税务网站报税':'了解利得税电子报税流程及所需文件。','周年申报逾期会发生什么':'了解申报期限、费用和逾期影响。','香港公司需要保存哪些会计和业务资料':'了解发票、收据、银行结单、收入及开支记录。','利得税报税表需要准备哪些材料':'了解财务报表、税项计算表及相关附件。','如何确认周年申报是否需要尽快处理':'了解私人公司周年申报期限和提交要求。','香港公司如何处理利得税电子申报':'了解电子报税入口、流程及提交文件。','如何查询业务是否需要香港牌照':'查询业务所需牌照、许可证、证书及批准要求。','香港公司申请撤销注册需要满足什么条件':'了解不营运、有偿债能力、债务和法律程序等条件。','撤销公司前为什么需要税务局不反对通知书':'了解不反对通知书的作用、申请人及基本程序。','如何申请不反对撤销公司注册通知书':'了解申请方式、处理程序及税务事项要求。'
};
const guideCardCopies={en:[['Hong Kong’s open business environment','Invest Hong Kong'],['Go global through Hong Kong','Invest Hong Kong'],['Hong Kong’s connectivity advantages','Invest Hong Kong']],vi:[['Môi trường kinh doanh cởi mở của Hồng Kông','Invest Hong Kong'],['Vươn ra toàn cầu qua Hồng Kông','Invest Hong Kong'],['Lợi thế kết nối của Hồng Kông','Invest Hong Kong']], 'pt-BR':[['Ambiente de negócios aberto de Hong Kong','Invest Hong Kong'],['Conecte-se ao mundo por Hong Kong','Invest Hong Kong'],['Vantagens de conectividade de Hong Kong','Invest Hong Kong']]};
function practicalInfo(type='pre-hk',conclusion=''){const items=preGuides[conclusion]||preGuides['适合启动'],localized=null;return `<section class="practical-info"><div class="practical-heading"><div><h2>${T('guide.title')}</h2></div></div><p class="practical-subtitle">${T('guide.subtitle')}</p><div class="practical-list">${items.map((x,i)=>{const copy=localized?.[i]||[translate(x[0],state.locale),translate(x[1],state.locale)];return `<button type="button" data-guide-type="pre-hk" data-guide-conclusion="${escape(conclusion)}" data-guide-index="${i}"><img class="guide-art" src="/assets/${['guide-1.png','guide-2.png','guide-3.png'][i]}" alt=""><span><b>${escape(copy[0])}</b><small>${escape(copy[1])}</small></span></button>`}).join('')}</div></section>`}
function loginRequired(){return `<div class="login-gate-curtain" data-action="cancel-login-gate"></div><section class="login-gate" role="dialog" aria-modal="true" aria-labelledby="loginGateTitle"><span>${escape(translate('AI 跨境顾问',state.locale))}</span><h2 id="loginGateTitle">${escape(translate('登录后才能开始对话',state.locale))}</h2><p>${escape(translate('登录后，AI 才能结合你的企业信息和评估记录提供建议，并保存本次沟通。',state.locale))}</p><div><button class="secondary" data-action="cancel-login-gate">${escape(translate('暂不登录',state.locale))}</button><button class="primary" data-action="login-for-chat">${escape(translate('去登录',state.locale))}</button></div></section>`}
function home(){const crossEnabled=crossUI.isEnabled(),personalized=state.homeData?.mode==='personalized'&&state.homeData?.type!=='in-hk'&&state.homeData?.type!=='cross-border',type='pre-hk',conclusion=state.homeData?.conclusion||state.homeData?.result?.conclusion||'',content=!state.token?(crossEnabled?'':newHome()):state.homeLoading?homeLoading():personalized?assessedHome():(crossEnabled?'':newHome()),crossEntry=crossEnabled?crossUI.homeEntry():'';return `<section class="page home-page ${personalized?'personalized':crossEnabled?'cross-entry-home':''}">${topbar()}<div class="hero"><div class="face idle" aria-label="AI顾问表情"><i></i></div><h1>跨国注册公司，AI 帮你规划</h1><p>已帮助 650+ 企业了解跨国注册公司的选择</p><div class="askbox"><input id="heroAsk" aria-label="向AI提问" placeholder="问一问  ${type==='in-hk'?'香港公司后续怎么做':'我想在香港开公司'}"><button type="button" data-action="voice-input" data-voice-target="heroAsk" aria-label="开始语音输入" aria-pressed="false">${icons.mic}</button></div><div class="voice-status" role="status" aria-live="polite"></div></div><main class="home-content">${content}${crossEntry}${practicalInfo(type,conclusion)}<footer class="home-footer"><div class="footer-mark"><div class="wordmark">跨境通<small>gopathway.tech</small></div></div><button data-route="about"><b>关于我们</b><span>→</span></button><button data-route="cooperation"><b>商务合作</b><span>→</span></button><button data-route="contact"><b>联系我们</b><span>→</span></button></footer></main>${state.profileOpen?profilePanel():''}${state.loginPrompt?loginRequired():''}</section>`}
function login(){const forChat=localStorage.getItem('hk-pending-type')==='chat';return `<section class="page no-nav login-page"><header class="login-nav"><button data-action="back" aria-label="返回">←</button><div><b>登录／注册</b></div><span></span></header><div class="login-banner"><div class="wordmark">跨境通<small>gopathway.tech</small></div></div><div class="login-body"><div class="login-copy">${crossUI.isEnabled()?`<p class="kicker">${escape(crossUI.targetLabel())}</p>`:''}<h1>${forChat?'登录后咨询 AI 跨境顾问':'继续你的公司注册评估'}</h1><p>${forChat?'登录后，AI 可结合企业信息与评估记录提供建议':'请先登录，完成评估后，可获得与你企业情况匹配的服务资源'}</p></div><form class="login-form" id="loginForm" novalidate><div class="login-field"><label class="sr-only" for="phone">手机号码</label><input id="phone" name="phone" inputmode="numeric" autocomplete="tel" placeholder="手机号码" value="${escape(state.phone)}" required aria-describedby="phoneError"><div id="phoneError" class="field-error"></div></div><div class="login-field code-field"><label class="sr-only" for="code">验证码</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" placeholder="验证码" required aria-describedby="codeError"><button type="button" data-action="fill-demo-code">获取验证码</button><div id="codeError" class="field-error"></div></div><button class="login-submit" type="submit">${forChat?'登录并开始咨询':'登录并开始评估'}</button><p class="login-agreement">登录即表示同意《用户协议》和《隐私政策》</p></form></div></section>`}
function accountSync(){return `<section class="page no-nav account-sync-page" aria-busy="true">${aiLoader('正在关联账号','正在同步账号信息，请稍候…')}</section>`}
function start(type){if(type==='cross-country'&&crossUI.isEnabled()){crossUI.chooseCountry();return;}if(type!=='chat'&&crossUI.isEnabled()){crossUI.start();return;}if(type==='in-hk')type='pre-hk';if(type==='chat'){state.route=state.token?'chat':'login';if(state.token&&!state.chatLoaded)state.chat=readCachedChat(state.token);render();if(state.token)loadChatHistory();return}state.assessmentType='pre-hk';state.answers=state.token?JSON.parse(localStorage.getItem(draftKey('pre-hk'))||'{}'):{};state.index=0;state.result=null;if(!state.token){state.route='login';localStorage.setItem('hk-pending-type','pre-hk');}else state.route='question';render();}
function questions(){return visibleQuestions(state.assessmentType,state.answers)}
function currentQuestion(){const qs=questions();state.index=Math.max(0,Math.min(state.index,qs.length-1));return {q:qs[state.index],qs};}
function optionSelected(q,o){const v=state.answers[q.id];return Array.isArray(v)?v.includes(o):v===o}
function questionHelp(q){if(q.id==='F03')return '可多选，根据企业实际经营范围选择一个或多个地区。';if(q.type==='multi-primary')return `可多选${q.max?`，最多选择 ${q.max} 项`:''}，并确认最主要的一项。`;if(q.type.startsWith('multi'))return `可多选${q.max?`，最多选择 ${q.max} 项`:''}。`;return '请选择最符合实际情况的一项。'}
function needsOther(q,v){return !!q.other&&Array.isArray(v)&&v.includes('其他')}
function questionValid(q,v,primary){return (Array.isArray(v)?v.length>0:!!v)&&(!needsOther(q,v)||!!String(state.answers[q.id+'_other']||'').trim())&&!(q.type==='multi-primary'&&Array.isArray(v)&&v.length>1&&!primary)}
function questionCanContinue(q,v){return (Array.isArray(v)?v.length>0:!!v)&&(!needsOther(q,v)||!!String(state.answers[q.id+'_other']||'').trim())}
function otherInput(q,v){return needsOther(q,v)?`<label class="other-answer"><span>请补充说明</span><input data-other-for="${q.id}" maxlength="${q.other.max}" value="${escape(state.answers[q.id+'_other']||'')}" placeholder="${escape(q.other.placeholder)}"><small>最多 ${q.other.max} 字</small></label>`:''}
function question(){const {q,qs}=currentQuestion();if(!q)return review();const v=state.answers[q.id];const primary=state.answers[q.id+'_primary'],canContinue=questionCanContinue(q,v);return `<section class="page no-nav question-page"><header class="question-nav"><button data-action="back">←　返回</button></header><div class="question-progress"><i style="width:${(state.index+1)/qs.length*100}%"></i></div><div class="question"><span class="kicker">${state.assessmentType==='in-hk'?'了解香港公司':'了解你的业务'}</span><h1>${escape(q.title)}</h1><p>${escape(questionHelp(q))}</p><div class="options">${q.options.map(o=>`<button class="option choice-${q.type} ${optionSelected(q,o)?'selected':''}" data-option="${escape(o)}" aria-pressed="${optionSelected(q,o)}"><i class="check" aria-hidden="true"></i><span>${escape(o)}</span></button>`).join('')}</div>${otherInput(q,v)}${q.type==='multi-primary'&&Array.isArray(v)&&v.length>1?`<div class="primary-picker"><h3>哪一项是最主要的？</h3><div class="options">${v.map(o=>`<button class="option choice-single ${primary===o?'selected':''}" data-primary="${escape(o)}" aria-pressed="${primary===o}"><i class="check" aria-hidden="true"></i><span>${escape(o)}</span></button>`).join('')}</div></div>`:''}</div><div class="bottom-actions"><button class="secondary" data-action="prev-question" ${state.index===0?'disabled':''}>上一步</button><button class="primary" data-action="next-question" ${!canContinue?'disabled':''}>${state.index===qs.length-1?'确认答案':'下一步'}</button></div></section>`}
function editSheet(q){if(!q)return '';const v=state.answers[q.id],primary=state.answers[q.id+'_primary'];return `<div class="sheet-backdrop" data-action="cancel-edit"></div><section class="edit-sheet" role="dialog" aria-modal="true" aria-labelledby="editTitle"><header><div><span>修改选项</span><h2 id="editTitle">${escape(q.title)}</h2></div><button data-action="cancel-edit" aria-label="关闭">×</button></header><div class="sheet-options">${q.options.map(o=>`<button class="option choice-${q.type} ${optionSelected(q,o)?'selected':''}" data-option="${escape(o)}" aria-pressed="${optionSelected(q,o)}"><i class="check"></i><span>${escape(o)}</span></button>`).join('')}</div>${q.type==='multi-primary'&&Array.isArray(v)&&v.length>1?`<div class="sheet-primary"><h3>哪一项是最主要的？</h3>${v.map(o=>`<button class="option choice-single ${primary===o?'selected':''}" data-primary="${escape(o)}"><i class="check"></i><span>${escape(o)}</span></button>`).join('')}</div>`:''}<footer><button class="secondary" data-action="cancel-edit">取消</button><button class="primary" data-action="finish-edit">完成</button></footer></section>`}
function review(){const qs=questions(),editing=state.editingIndex===null?null:qs[state.editingIndex];return `<section class="page no-nav">${topbar('确认信息',true)}<div class="review"><h1>确认一下企业情况</h1><p>以下信息将用于生成你的评估，请确认是否准确。</p><div class="review-group">${qs.map((q,i)=>{let v=state.answers[q.id];if(q.type==='multi-primary'&&state.answers[q.id+'_primary'])v=[`主要：${state.answers[q.id+'_primary']}`,...v.filter(x=>x!==state.answers[q.id+'_primary'])];return `<button class="review-row" data-edit-index="${i}"><span>${escape(q.title.replace(/[？?]$/,''))}</span><b>${escape(Array.isArray(v)?v.join('、'):v||'')}</b><em>编辑</em></button>`}).join('')}</div></div><div class="bottom-actions"><button class="secondary" data-action="back-question">返回修改</button><button class="primary" data-action="submit-assessment" ${state.submitting?'disabled':''}>${state.submitting?'正在提交':'开始评估'}</button></div>${editSheet(editing)}</section>`}
function analysis(){const inHK=state.assessmentType==='in-hk',steps=['读取企业基本情况','识别当前业务阶段','核对跨境需求与目标','检查需要确认的事项','计算评估结论','生成下一步建议'];return `<section class="page no-nav">${topbar('AI评估',false)}<div class="analysis" aria-busy="true">${aiLoader(`正在生成你的${inHK?'在港状态':'赴港'}评估`,'正在核对企业信息，并按照评估规则形成结论')}<div class="analysis-list">${steps.map((s,i)=>`<div class="analysis-step ${i===0?'active':''}" data-analysis-step="${i}"><i></i><span>${s}</span></div>`).join('')}</div><p class="fine analysis-note">结论由确定性规则生成，AI不会修改评分或结论。</p></div></section>`}
const dimLabel=(n,max)=>{const p=n/max*100;return p>=80?'准备充分':p>=60?'基础稳定':p>=40?'需要确认':'尚待准备'};
function radar(d){const vals=[d.compliance/25,d.hkValue/35,d.crossBorder/20,d.business/20];const pts=vals.map((v,i)=>{const a=(-90+i*90)*Math.PI/180;return `${70+Math.cos(a)*52*v},${70+Math.sin(a)*52*v}`}).join(' ');return `<svg class="radar" viewBox="0 0 140 140" role="img" aria-label="企业赴港四维雷达图"><polygon points="70,14 126,70 70,126 14,70"/><polygon points="70,35 105,70 70,105 35,70"/><line x1="70" y1="14" x2="70" y2="126"/><line x1="14" y1="70" x2="126" y2="70"/><polygon class="radar-value" points="${pts}"/></svg>`}
const resultIconMap={'本次判断依据':'why','你的企业赴港情况':'situation','香港公司当前情况':'situation','业务特点':'business','需要进一步确认':'confirm','需要特别关注':'risk','优先处理与待完善事项':'risk','初步公司定位':'building','初步架构方向':'network','下一步建议':'route'};
const resultPlanLabel=r=>(r.type==='in-hk'?{'注册审批中':'查看成立后准备清单','成立待运营':'获取成立后待办清单','当前运行基本正常':'查看日常维护建议','有事项待完善':'查看我的完善清单','需要优先核验':'查看优先处理事项','退出安排待梳理':'查看停止经营准备清单'}:{'适合启动':'制定我的赴港计划','具备基础':'完善我的赴港方案','值得探索':'看看最值得先做什么','早期准备':'获取赴港准备清单'})[r.conclusion]||'查看推荐方案';
function resultCard(title,content){const icon=resultIconMap[title]||'route';if(title==='本次判断依据'&&state.result?.basis)content=`<p>${escape(state.result.basis)}</p>`;if(title==='下一步建议'){const tasks=(state.result?.actions?.length?state.result.actions:['补充交易路径与合规安排','核对公司注册、秘书及持续维护要求','匹配法律和财税专业服务']);content=`<ol class="result-task-list">${tasks.slice(0,3).map((x,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><span><strong>${escape(x)}</strong><small>${i===0?'现在优先处理':'完成上一项后继续'}</small></span></li>`).join('')}</ol>`}return `<section class="result-card"><h2><img src="/assets/icon-${icon}.svg" alt="">${escape(title)}</h2>${content}</section>`}
function result(){const r=state.result;if(!r||r.type==='in-hk')return home();if(false)return `<section class="page no-nav result-page">${topbar('评估结果',true)}<div class="result-hero in-hk"><img src="/assets/result-check.svg" alt=""><h1>${escape(r.title)}</h1><p>${escape(r.summary)}</p>${resultCard('本次判断依据',`<p>${escape(r.companyStatus||'根据香港公司的实际运营状态生成结论。')}</p>`,'⌕')}</div><div class="result-content">${resultCard('香港公司当前情况',`<ul>${[r.companyStatus,...r.roles].filter(Boolean).map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'◎')}${resultCard('优先处理与待完善事项',`<ul>${(r.issues.length?r.issues:['目前没有明显需要优先处理的事项']).map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'△')}${resultCard('下一步建议',`<ul>${(r.actions.length?r.actions:['确认公司成立后的账户、合同、会计记录与持续维护安排']).map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'↗')}<div class="result-actions"><button class="primary red" data-route="home">${escape(resultPlanLabel(r))}</button><button class="primary" data-action="open-chat">问问AI</button><button class="text-action" data-action="restart">重新评估</button></div></div></section>`;const d=r.dimensions;return `<section class="page no-nav result-page">${topbar('评估结果',true)}<div class="result-hero"><img src="/assets/result-check.svg" alt=""><h1>${escape(r.title)}</h1><p>${escape(r.summary)}</p>${resultCard('本次判断依据',`<p>${escape(r.conclusion==='具备基础'?'企业已有一定海外业务基础和明确赴港目的，但交易路径与主体分工仍需完善。':r.summary)}</p>`,'⌕')}</div><div class="result-content">${resultCard('你的企业赴港情况',`<p class="card-note">我们从四个方面分析香港是否能为企业带来实际价值。</p><div class="radar-layout"><div class="radar-top"><b>行业及合规</b><span>${dimLabel(d.compliance,25)}</span></div><div class="radar-mid"><div><b>企业业务基础</b><span>${dimLabel(d.business,20)}</span></div>${radar(d)}<div><b>香港发展价值</b><span>${dimLabel(d.hkValue,35)}</span></div></div><div class="radar-bottom"><b>跨境业务需求</b><span>${dimLabel(d.crossBorder,20)}</span></div><p class="radar-note">图形越靠外，表示该维度的准备程度越充分。</p></div>`,'◎')}${resultCard('业务特点',`<ul>${r.features.map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'▣')}${resultCard('需要进一步确认',`<p>确认主要交易币种、付款方地区和合同主体，判断香港公司适合承担的角色。</p>`,'?')}${resultCard('需要特别关注',`<p>${escape(r.attention?.length?'围绕 '+r.attention.join('、')+'建立真实合同、订单、交付和资金路径。':'账户安排需要建立在真实合同、订单、交付和资金路径基础上。')}</p>`,'△')}${resultCard('初步公司定位',`<p><b>${escape(r.position)}</b>：围绕真实跨境业务承担相应职能并保留完整业务证明。</p>`,'⌂')}${resultCard('初步架构方向',`<p>先采用单一香港主体承接最明确的跨境业务，需求稳定后再评估增加持股层级。</p>`,'↗')}${resultCard('下一步建议',`<p>先补充交易路径与合规安排，再匹配公司注册、秘书、法律和财税服务。</p>`,'↗')}<div class="result-actions"><button class="primary red" data-route="home">${escape(resultPlanLabel(r))}</button><button class="primary" data-action="open-chat">问问AI</button><button class="text-action" data-action="restart">重新评估</button></div></div></section>`}
function chat(){const initial=state.result?`我已经看过你的“${state.result.conclusion}”评估。你可以问我为什么得到这个结论，或现在最应该先做什么。`:'告诉我你的业务目标，我会帮你梳理公司注册的准备事项。';if(!state.chat.length){state.chat.push({id:'welcome',role:'assistant',content:initial,createdAt:Date.now()});persistChat()}const latestAssistant=state.chat.findLastIndex(m=>m.role==='assistant');return `<section class="page no-nav chat-page">${topbar('AI跨境顾问',true)}<div class="chat-log" id="chatLog" aria-live="polite">${state.chat.map((m,index)=>{const chunks=m.role==='assistant'?splitAssistantReply(m.content):[m.content];return `<div class="chat-message ${m.role}">${chunks.map(content=>`<div class="bubble ${m.role==='user'?'user':'assistant'}">${chatMessageHtml({...m,content})}</div>`).join('')}${m.role==='assistant'&&index===latestAssistant?chatActionHtml(m.action):''}</div>`}).join('')}${state.chatLoading?'<div class="chat-history-loading">正在同步历史对话…</div>':''}${state.submitting?'<div class="bubble assistant thinking-bubble" role="status"><i></i><i></i><i></i><span class="sr-only">AI正在思考</span></div>':''}</div><div class="chat-voice-status voice-status" role="status" aria-live="polite"></div><form class="chat-compose" id="chatForm"><button class="chat-voice" type="button" data-action="voice-input" data-voice-target="chatMessage" aria-label="开始语音输入" aria-pressed="false" ${state.submitting?'disabled':''}>${icons.mic}</button><input id="chatMessage" name="message" aria-label="输入问题" placeholder="${state.submitting?'AI 正在思考…':'输入你想了解的问题'}" required ${state.submitting?'disabled':''}><button class="chat-send" type="submit" aria-label="发送消息" ${state.submitting?'disabled':''}>${icons.send}</button></form></section>`}
function scrollChatToLatest(behavior='auto'){requestAnimationFrame(()=>{const log=document.querySelector('#chatLog');if(log)log.scrollTo({top:log.scrollHeight,behavior})})}
async function loadChatHistory(){if(!state.token||state.chatLoading||state.chatLoaded)return;state.chatLoading=true;if(state.route==='chat')render();try{const d=await api('/api/chat/history');const cloud=clearTransientChatActions(d.messages),local=clearTransientChatActions(state.chat).filter(m=>!cloud.some(c=>c.id===m.id));const merged=[...cloud,...local].filter((m,index,all)=>all.findIndex(x=>x.id===m.id)===index).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0));if(merged.length)state.chat=merged;state.chatLoaded=true;persistChat()}catch{state.chatLoaded=true}finally{state.chatLoading=false;if(state.route==='chat'){const draft=document.querySelector('#chatMessage')?.value||'';render();requestAnimationFrame(()=>{const input=document.querySelector('#chatMessage');if(input&&draft)input.value=draft;scrollChatToLatest()})}}}
async function sendChatMessage(msg){if(!msg||state.submitting)return;const requestId=crypto.randomUUID?.()||`${Date.now()}${Math.random()}`,temporaryId=`local-${requestId}`;state.chat.push({id:temporaryId,role:'user',content:msg,createdAt:Date.now()});persistChat();state.submitting=true;render();scrollChatToLatest('smooth');try{const d=await api('/api/chat',{method:'POST',body:JSON.stringify({message:msg,requestId,locale:state.locale,context:{result:state.result},history:state.chat})});state.chat=state.chat.filter(m=>m.id!==temporaryId);if(d.messages?.length){const incoming=d.messages.map(m=>({...m}));const assistantIndex=incoming.map(m=>m.role).lastIndexOf('assistant');if(d.action&&assistantIndex>=0)incoming[assistantIndex].action=d.action;state.chat.push(...incoming)}else state.chat.push({id:`${requestId}-u`,role:'user',content:msg,createdAt:Date.now()},{id:`${requestId}-a`,role:'assistant',content:d.reply,action:d.action,createdAt:Date.now()+1});persistChat();render();scrollChatToLatest('smooth')}catch(err){const raw=String(err?.message||'');const content=/未知异常|unexpected|fetch|json|http/i.test(raw)?'AI顾问暂时没有响应，请重新发送一次。':raw||'暂时无法连接AI，请稍后重试。';state.chat.push({id:`${requestId}-error`,role:'assistant',content:translate(content,state.locale),createdAt:Date.now()+1});persistChat()}finally{state.submitting=false;render();scrollChatToLatest('smooth')}}
function profile(){return `<section class="page no-nav">${topbar('',true)}<h1 class="page-heading">我的</h1>${state.phone?`<div class="profile-head"><span class="avatar">${escape(state.phone.slice(-1))}</span><div><b>${escape(state.phone.slice(0,3)+' **** '+state.phone.slice(-4))}</b></div></div><div class="profile-list"><button data-route="account"><b>账号资料</b><span>手机、称呼与语言偏好　→</span></button><button data-route="company"><b>企业信息表</b><span>查看和编辑已确认的信息　→</span></button><button data-route="assessments"><b>我的评估与计划</b><span>${state.result?'已有 1 份评估结果':'暂无评估'}　→</span></button><button data-route="favorites"><b>收藏的服务商</b><span>查看收藏与比较列表　→</span></button><button data-route="about"><b>关于公司</b><span>${T('profile.aboutLine')}　→</span></button><button data-route="cooperation"><b>商务合作</b><span>服务商与机构合作　→</span></button><button data-route="contact"><b>联系我们</b><span>服务时间与问题反馈　→</span></button></div><div class="content"><button class="secondary" data-action="logout">退出登录</button></div>`:'<div class="empty"><p>登录后查看企业信息、评估记录和收藏内容。</p><button class="primary" data-route="login">去登录</button></div>'}</section>`}
