 const type=providerRecordText(p,['服务商类型','机构类型'],state.locale,{controlled:true,fallback:T('provider.type')}),intro=providerRecordText(p,['服务商简介','机构简介','简介'],state.locale,{fallback:providerNarrativeCopy[state.locale]?.details||c.unspecified}),details=providerRecordText(p,['服务内容说明'],state.locale,{fallback:providerNarrativeCopy[state.locale]?.details||c.unspecified}),excluded=p['不包含的服务']?providerRecordText(p,['不包含的服务'],state.locale,{fallback:providerNarrativeCopy[state.locale]?.excluded||c.unspecified}):'';
