let idleFaceIndex=0,recognition=null,voiceStatusTimer=null;
let lastViewKey='';
const faceStates=['idle','glance-left','idle','glance-right','idle'];
function setFace(name){const face=document.querySelector('.hero .face');if(face){face.className=`face ${name}`;face.setAttribute('aria-label',`AI: ${name}`)}}
function voiceInput(button){
 const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
 const status=button.closest('.hero')?.querySelector('.voice-status')||document.querySelector('.chat-voice-status');
 const setStatus=(message,kind='active',linger=0)=>{if(!status)return;message=escape(translate(message,state.locale));clearTimeout(voiceStatusTimer);status.className=`${status.classList.contains('chat-voice-status')?'chat-voice-status ':''}voice-status ${kind}`;status.innerHTML=kind==='active'?`<i></i><i></i><i></i><span>${message}</span>`:`<span>${message}</span>`;if(linger)voiceStatusTimer=setTimeout(()=>{status.textContent='';status.classList.remove('active','error','success')},linger)};
 if(!Speech){setStatus('当前浏览器暂不支持语音输入','error',3200);toast('当前浏览器暂不支持语音输入');return}
 if(button.classList.contains('recording')){setStatus('正在结束并识别…','active');recognition?.stop();return}
 recognition?.abort();
 recognition=new Speech();recognition.lang=state.locale==='zh-HK'?'zh-HK':state.locale;recognition.interimResults=true;recognition.continuous=false;
 const target=document.getElementById(button.dataset.voiceTarget||'heroAsk');
 let receivedResult=false,failed=false;
 const resetButton=()=>{button.classList.remove('recording');button.setAttribute('aria-pressed','false');button.setAttribute('aria-label','开始语音输入');setFace('idle')};
 setFace('listening');button.classList.add('recording');button.setAttribute('aria-pressed','true');button.setAttribute('aria-label','停止语音输入');setStatus('正在连接麦克风…','active');
 recognition.onstart=()=>setStatus('正在收音，再次点击麦克风结束','active');
 recognition.onaudiostart=()=>setStatus('正在收音，再次点击麦克风结束','active');
 recognition.onspeechstart=()=>setStatus('已检测到声音，正在识别…','active');
 recognition.onresult=e=>{const text=[...e.results].map(x=>x[0].transcript).join('').trim();if(text){receivedResult=true;if(target){target.value=text;target.dispatchEvent(new Event('input',{bubbles:true}))}setStatus('已识别为文字','success',2200)}};
 recognition.onerror=e=>{failed=true;const messages={'not-allowed':'麦克风权限未开启，请在浏览器设置中允许','service-not-allowed':'浏览器未允许使用语音服务','audio-capture':'未检测到可用麦克风','network':'语音服务连接失败，请检查网络','no-speech':'未检测到声音，请靠近麦克风再试','aborted':'语音输入已取消'};const message=messages[e.error]||'语音输入暂时不可用，请重试';resetButton();setStatus(message,'error',3600);toast(message)};
 recognition.onend=()=>{resetButton();if(failed)return;if(receivedResult)setStatus('已识别为文字','success',2200);else setStatus('未检测到声音，请靠近麦克风再试','error',3600)};
 try{recognition.start()}catch{failed=true;resetButton();setStatus('语音输入暂时不可用，请重试','error',3600);toast('语音输入暂时不可用，请重试')}
}
function render(preserveScroll=false){const previousScroll=app.scrollTop,viewKey=state.route==='question'?`question:${state.index}`:state.route,entering=viewKey!==lastViewKey;const routes={home,login,accountSync,question,review,analysis,result,chat,profile,account,company,assessments,favorites,provider,guide,about,cooperation,contact};app.innerHTML=crossUI.render()??(routes[state.route]||home)();if(state.route==='home')preloadProviderDetails(state.homeData);app.querySelectorAll('.profile-head>div').forEach(el=>{const line=document.createElement('small');line.className='profile-user-id';line.textContent=translate(`用户ID ${userIdFromToken(state.token)}`,state.locale);el.append(line)});localize(app,state.locale);app.classList.toggle('modal-open',state.editingIndex!==null);if(entering)app.querySelector('.page')?.classList.add('page-enter');lastViewKey=viewKey;if(state.route==='result'&&state.result){const hero=app.querySelector('.result-hero'),tag=document.createElement('span');tag.className='conclusion-tag';tag.textContent=translate(state.result.conclusion,state.locale);hero?.querySelector('img')?.after(tag)}if(preserveScroll){const restore=()=>{app.scrollTop=previousScroll};requestAnimationFrame(()=>{restore();requestAnimationFrame(restore);setTimeout(restore,80)})}else{app.scrollTop=0;window.scrollTo(0,0)}}
async function loadHome(force=false,preferredType=''){if(!state.token||state.homeLoading||state.homeData&&!force)return;state.homeLoading=true;if(['home','assessments'].includes(state.route))render();const type=['pre-hk','in-hk'].includes(preferredType)?preferredType:'';try{state.homeData=await api(`/api/home${type?`?type=${type}`:''}`);if(state.homeData?.mode==='new')state.result=null;if(state.homeData?.assessmentType)state.assessmentType=state.homeData.assessmentType;if(state.homeData?.result){state.result=state.homeData.result;localStorage.setItem(userKey('latest-result',state.token),JSON.stringify(state.result))}preloadProviderDetails(state.homeData)}catch(err){if(err.message==='请先登录')clearUserState();else toast('暂时无法读取最新评估')}finally{state.homeLoading=false;if(['home','assessments'].includes(state.route))render()}}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='cancel-login-gate'){e.preventDefault();e.stopImmediatePropagation();state.loginPrompt=false;render();return}if(action==='login-for-chat'){e.preventDefault();e.stopImmediatePropagation();state.loginPrompt=false;localStorage.setItem('hk-pending-type','chat');state.returnRoute='home';state.route='login';render();return}if(!state.token&&(action==='voice-input'||action==='ask-home'||action==='open-chat')){e.preventDefault();e.stopImmediatePropagation();state.loginPrompt=true;render()}},true);
