document.addEventListener('click',e=>{const button=e.target.closest('[data-guide-index]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const type=button.dataset.guideType,conclusion=button.dataset.guideConclusion,inHK=type==='in-hk',items=(inHK?inGuides[conclusion]:preGuides[conclusion])||(inHK?inGuides['成立待运营']:preGuides['适合启动']),item=items[Number(button.dataset.guideIndex)];if(!item)return;state.selectedGuide={title:item[0],source:item[1],url:item[2],description:guideDescriptions[item[0]]||'查看与当前评估阶段相关的官方说明和办理要求。',cover:button.querySelector('img')?.getAttribute('src')||'/assets/guide-prepare.svg',type};state.returnRoute='home';state.route='guide';render()},true);
document.addEventListener('click',async e=>{const providerButton=e.target.closest('[data-provider-id]'),retry=e.target.closest('[data-action="retry-provider"]');if(!providerButton&&!retry)return;e.preventDefault();e.stopImmediatePropagation();const id=providerButton?.dataset.providerId||state.providerId;if(!id)return;state.providerId=id;if(providerButton)state.returnRoute=state.route;state.selectedProvider=null;state.providerLoadError='';state.providerLoading=true;state.route='provider';const request=++state.providerRequest;render();try{const provider=await fetchProviderDetail(id);if(state.providerRequest!==request||state.route!=='provider')return;state.selectedProvider=provider;state.providerLoading=false;render()}catch(error){if(state.providerRequest!==request||state.route!=='provider')return;state.providerLoading=false;state.providerLoadError=error.message||'请求失败';render()}},true);
document.addEventListener('click',async e=>{const providerButton=e.target.closest('[data-provider-id]');if(providerButton){state.returnRoute='home';try{const d=await api('/api/providers/'+encodeURIComponent(providerButton.dataset.providerId));state.selectedProvider=d.provider;state.route='provider';render()}catch(err){toast(err.message)}return}const route=e.target.closest('[data-route]');if(route){if(route.dataset.route==='profile'&&state.route==='home'){state.profileOpen=true;render();return}const completedType=state.route==='result'?state.result?.type:'';state.profileOpen=false;state.returnRoute=state.route;state.route=route.dataset.route;render();if(state.route==='home')loadHome(true,completedType);if(state.route==='assessments')loadHome(!state.homeData);return}const startBtn=e.target.closest('[data-start]');if(startBtn){start(startBtn.dataset.start);return}const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action;if(action==='close-profile'){state.profileOpen=false;render()}if(action==='edit-account'){state.accountEditing=true;render();requestAnimationFrame(()=>document.querySelector('#displayName')?.focus())}if(action==='cancel-account-edit'){state.accountEditing=false;render()}if(action==='edit-company'){state.companyEditing=true;render();requestAnimationFrame(()=>document.querySelector('#companyForm input')?.focus())}if(action==='cancel-company-edit'){state.companyEditing=false;render()}if(action==='back'){state.accountEditing=false;state.companyEditing=false;state.route=state.route==='question'?'home':state.route==='review'?'question':state.route==='chat'?'home':state.returnRoute||'home';state.returnRoute='home';render();if(state.route==='home')loadHome()}if(action==='assessment-hub')start('pre-hk');if(action==='service-toast')toast('该服务将在服务商数据库完成后开放');if(action==='voice-input')voiceInput(a);if(action==='ask-home'||action==='open-chat'){state.returnRoute=state.route;state.route='chat';render()}if(action==='prev-question'){state.index--;render()}if(action==='back-question'){state.index=Math.max(0,questions().length-1);state.route='question';render()}if(action==='next-question'){const {q,qs}=currentQuestion();if(q.skip&&q.skip(state.answers))state.answers[q.id]=q.autoValue;if(state.index>=qs.length-1){state.route='review'}else state.index++;localStorage.setItem(draftKey(state.assessmentType),JSON.stringify(state.answers));render()}if(action==='submit-assessment')submitAssessment();if(action==='restart'){localStorage.removeItem(draftKey(state.assessmentType));start(state.assessmentType)}if(action==='logout'){localStorage.removeItem('hk-token');localStorage.removeItem('hk-phone');localStorage.removeItem('hk-latest-result');state.token='';state.phone='';state.result=null;state.homeData=null;state.profileOpen=false;state.route='home';render()}}const opt=e.target.closest('[data-option]');if(opt){selectOption(currentQuestion().q,opt.dataset.option)}const primary=e.target.closest('[data-primary]');if(primary){state.answers[currentQuestion().q.id+'_primary']=primary.dataset.primary;render()}const edit=e.target.closest('[data-edit-index]');if(edit){state.index=Number(edit.dataset.editIndex);state.route='question';render()}});
