document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-index]'),action=e.target.closest('[data-action]')?.dataset.action;if(edit){e.preventDefault();e.stopImmediatePropagation();state.editingBackup=JSON.parse(JSON.stringify(state.answers));state.editingIndex=Number(edit.dataset.editIndex);state.index=state.editingIndex;render();return}if(state.editingIndex!==null&&(action==='cancel-edit'||action==='finish-edit')){e.preventDefault();e.stopImmediatePropagation();if(action==='cancel-edit')state.answers=state.editingBackup;else localStorage.setItem(draftKey(state.assessmentType),JSON.stringify(state.answers));state.editingIndex=null;state.editingBackup=null;render()}},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-action="next-question"]')){const q=currentQuestion().q,v=state.answers[q?.id];if(q?.type==='multi-primary'&&Array.isArray(v)&&v.length>1&&!state.answers[q.id+'_primary']){e.preventDefault();e.stopImmediatePropagation();const picker=document.querySelector('.primary-picker');picker?.classList.add('needs-answer');picker?.scrollIntoView({behavior:'smooth',block:'center'});toast('请选择最主要的一项')}}},true);
function advanceQuestion(){const {q,qs}=currentQuestion();if(q.skip&&q.skip(state.answers))state.answers[q.id]=q.autoValue;if(state.index>=qs.length-1)state.route='review';else state.index++;localStorage.setItem(draftKey(state.assessmentType),JSON.stringify(state.answers));render()}
function selectOption(q,o){if(q.type==='single'){state.answers[q.id]=o;if(q.id==='F04'&&o==='筹备中')state.answers.F05='尚未开始经营';localStorage.setItem(draftKey(state.assessmentType),JSON.stringify(state.answers));render(true);if(state.editingIndex===null)setTimeout(()=>{if(state.route==='question'&&currentQuestion().q?.id===q.id)advanceQuestion()},180);return}else{let v=[...(state.answers[q.id]||[])];const exclusive=(q.exclusive||[]).includes(o);if(v.includes(o))v=v.filter(x=>x!==o);else{if(exclusive)v=[o];else{v=v.filter(x=>!(q.exclusive||[]).includes(x));if(q.max&&v.length>=q.max)return toast(`最多选择 ${q.max} 项，请先取消一项`);v.push(o)}}state.answers[q.id]=v;if(!v.includes('其他'))delete state.answers[q.id+'_other'];if(q.type==='multi-primary'){const pk=q.id+'_primary';if(!v.includes(state.answers[pk]))state.answers[pk]=''}}render(true)}
document.addEventListener('input',e=>{const id=e.target.dataset.otherFor;if(!id)return;state.answers[id+'_other']=e.target.value;const q=currentQuestion().q,next=document.querySelector('[data-action="next-question"]');if(q&&next)next.disabled=!questionValid(q,state.answers[q.id],state.answers[q.id+'_primary']);localStorage.setItem(draftKey(state.assessmentType),JSON.stringify(state.answers))});
document.addEventListener('submit',async e=>{if(e.target.id!=='accountForm')return;e.preventDefault();e.stopImmediatePropagation();if(!state.accountEditing)return;const name=new FormData(e.target).get('displayName').trim();if(!name)return toast('请输入姓名或称呼');const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;submit.textContent=translate('保存中…',state.locale);try{await api('/api/account',{method:'POST',body:JSON.stringify({displayName:name})});localStorage.setItem(userKey('display-name',state.token),name);state.accountEditing=false;render();toast('账号资料已保存')}catch(err){submit.disabled=false;submit.textContent=translate('保存',state.locale);toast(err.message)}},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='companyForm')return;e.preventDefault();e.stopImmediatePropagation();if(!state.companyEditing)return;const fd=new FormData(e.target),profile=Object.fromEntries(['industry','location','stage','scale','goal'].map(k=>[k,String(fd.get(k)||'').trim()]));if(!profile.industry)return toast('请填写主营行业');const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;submit.textContent=translate('保存中…',state.locale);try{await api('/api/company',{method:'POST',body:JSON.stringify(profile)});localStorage.setItem(userKey('company-profile',state.token),JSON.stringify(profile));state.companyEditing=false;render();toast('企业信息已保存')}catch(err){submit.disabled=false;submit.textContent=translate('保存',state.locale);toast(err.message)}},true);
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='loginForm'){if(state.accountSyncing)return;const fd=new FormData(e.target),phone=fd.get('phone').trim(),code=fd.get('code').trim();const pe=document.querySelector('#phoneError'),ce=document.querySelector('#codeError');pe.textContent=/^1\d{10}$/.test(phone)?'':translate('请输入11位手机号',state.locale);ce.textContent=code?'':translate('请输入验证码',state.locale);if(pe.textContent||ce.textContent)return;const pending=localStorage.getItem('hk-pending-type')||'pre-hk';try{state.accountSyncing=true;const d=await api('/api/login',{method:'POST',body:JSON.stringify({phone,code})});state.token=d.token;state.phone=phone;localStorage.setItem('hk-token',d.token);localStorage.setItem('hk-phone',phone);state.route='accountSync';render();const synced=await syncAccountAfterLogin(d.token);if(!synced)throw new Error('账号信息同步失败，请重试');localStorage.removeItem('hk-pending-type');if(pending==='chat'){state.route='chat';state.returnRoute='home';state.chat=readCachedChat(state.token);state.chatLoaded=false;render();loadChatHistory()}else start('pre-hk')}catch(err){clearUserState();state.route='login';render();const currentError=document.querySelector('#codeError');if(currentError)currentError.textContent=translate(err.message,state.locale)}finally{state.accountSyncing=false}}if(e.target.id==='chatForm'){const input=e.target.elements.message,msg=input.value.trim();if(!msg)return;input.value='';await sendChatMessage(msg)}});
async function submitAssessment(){if(state.submitting)return;state.submitting=true;state.route='analysis';render();document.querySelectorAll('[data-analysis-step]').forEach((el,i)=>setTimeout(()=>{el.classList.remove('active');el.classList.add('done');const next=document.querySelector(`[data-analysis-step="${i+1}"]`);if(next)next.classList.add('active')},350*(i+1)));try{const d=await api(`/api/assess/${state.assessmentType}`,{method:'POST',body:JSON.stringify({answers:state.answers})});await new Promise(r=>setTimeout(r,2200));state.result=d.result;state.homeData=d.home||null;preloadProviderDetails(state.homeData);localStorage.setItem(userKey('latest-result',state.token),JSON.stringify(state.result));localStorage.removeItem(draftKey(state.assessmentType));state.route='result';if(!d.saved&&d.saveError)toast('评估已生成，飞书保存稍后重试')}catch(err){toast(err.message);state.route='review'}finally{state.submitting=false;render()}}
