async function restoreSession(){
 if(!state.token){render();return}
 render();
 try{
  const data=await api('/api/session');
  state.phone=data.user?.phone||'';
  localStorage.setItem('hk-phone',state.phone);
  state.result=JSON.parse(localStorage.getItem(userKey('latest-result',state.token))||'null');
  if(state.result?.type==='in-hk'){
   state.result=null;
   localStorage.removeItem(userKey('latest-result',state.token));
  }
  state.homeLoading=false;
  render();
  loadHome();
 }catch{
  clearUserState();
  state.route='home';
  render();
 }
}
restoreSession();
